// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new C(address(lg));
    }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 10 ether);
        vm.deal(actor, amount);
        uint256 before = lg.History();
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        uint256 after_ = lg.History();
        assertTrue(
            after_ == before + 1 && lg.History(after_ - 1).Sender == actor && lg.History(after_ - 1).Val == amount,
            "every deposit must append one Log entry recording sender and value"
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amt, uint unlockTime) public payable {
        require(address(this).balance >= amt);
        c.Put{value: amt}(unlockTime);
        c.Collect(amt);
        assert(c.Acc(address(this)).balance == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
