    constructor(C _c) { c = _c; }

    function test(uint amt, uint fut) public {
        require(amt > 0);
        require(fut > block.timestamp);
        require(address(this).balance >= amt);
        c.Put(fut){value: amt}();
        uint bal0 = c.Acc(address(this)).balance;
        c.Collect(amt);
        assert(c.Acc(address(this)).balance == bal0);
    }

    receive() external payable {}
    fallback() external payable {}
}

