contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {
        revert();
    }

    function run(uint amt) public {
        require(amt >= 1 ether);
        require(address(this).balance >= amt);

        c.Put{value: amt}(0);

        uint beforeBal = c.Acc(address(this)).balance;

        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.Collect.selector, amt)
        );
        ok;

        uint afterBal = c.Acc(address(this)).balance;

        assert(beforeBal == afterBal);
    }
}

