contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amt) public
    {
        require(amt > 1 ether, "amount must exceed MinSum");
        require(address(this).balance >= amt, "insufficient test balance");
        c.Put{value: amt}(0);
        // unlockTime is now block.timestamp; Collect in the same block must be rejected.
        c.Collect(amt);
        assert(address(c).balance >= amt);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest
{
    C c;
    Log lg;
    bool saw;

    constructor(C _c) { c = _c; }

    function test(Log _log, uint amt) public
    {
        require(address(this).balance >= amt);
        lg = _log;
        saw = false;
        c.Put{value: amt}(0);
        c.Collect(amt);
        assert(!saw);
    }

    receive() external payable
    {
        if (msg.sender == address(c))
        {
            try lg.History(1) { saw = true; } catch { }
        }
    }
}
